// src/main.cpp

#include <iostream>
#include <string>
#include <vector>
#include <cstring>
#include <unistd.h> // For close()
#include <sys/socket.h> // For socket operations
#include <netinet/in.h> // For sockaddr_in

// --- Constants ---
#define PORT 8080
#define BACKLOG 10
#define BUFFER_SIZE 1024

/**
 * @brief Handles a single client connection in a blocking manner.
 * @param client_socket The socket descriptor for the connected client.
 */
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE] = {0};
    ssize_t bytes_read;

    std::cout << "[SERVER] Waiting for data from client..." << std::endl;

    // Receive data from the client
    bytes_read = read(client_socket, buffer, BUFFER_SIZE - 1);
    if (bytes_read > 0) {
        std::string received_message(buffer, bytes_read);
        std::cout << "[SERVER] Received message: " << received_message;

        // Echo the message back to the client
        std::string response = "Echo: " + received_message;
        send(client_socket, response.c_str(), response.length(), 0);
        std::cout << "[SERVER] Sent echo response." << std::endl;
    } else if (bytes_read == 0) {
        std::cout << "[SERVER] Client disconnected gracefully." << std::endl;
    } else {
        perror("[SERVER] Read error");
    }

    // Close the client socket connection
    close(client_socket);
}

/**
 * @brief Initializes and runs the main server loop.
 */
int main() {
    std::cout << "--- Simple Echo Server Starting ---" << std::endl;

    // 1. Create socket file descriptor
    int server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("[FATAL] Could not create socket");
        return 1;
    }
    std::cout << "[SERVER] Socket created successfully." << std::endl;

    // Optional: Set socket options to reuse address/port
    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt)) < 0) {
        perror("[WARNING] setsockopt failed");
    }

    // 2. Bind the socket to the specified IP and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY; // Listen on all available interfaces
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("[ERROR] Bind failed");
        close(server_fd);
        return 1;
    }
    std::cout << "[SUCCESS] Server bound to port " << PORT << std::endl;

    // 3. Start listening for incoming connections
    listen(server_fd, 10);
    std::cout << "[SUCCESS] Server listening for connections..." << std::endl;

    // 4. Main accept loop
    int new_socket;
    struct sockaddr_storage client_addr;
    socklen_t client_len = sizeof(client_addr);

    while (true) {
        std::cout << "\n[WAITING] Accepting new connection..." << std::endl;
        new_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (new_socket < 0) {
            perror("[ERROR] Accept failed");
            continue;
        }
        std::cout << "[CONNECTED] Client connected. Handling request..." << std::endl;

        // Handle the client connection (synchronous blocking approach for simplicity)
        handle_client(new_socket);

        // Close the client socket after handling
        close(new_socket);
        std::cout << "[DISCONNECTED] Client connection closed." << std::endl;
    }

    // Cleanup (unreachable in this infinite loop, but good practice)
    close(server_fd);
    return 0;
}

